#include <stdlib.h>
#include <string.h>
#include <math.h>
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*n){HE top=h[0];HE x=h[--(*n)];int i=0,N=*n;for(;;){int c=2*i+1;if(c>=N)break;if(c+1<N&&h[c+1].d<h[c].d)c++;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}if(N>0)h[i]=x;return top;}

/* sparse SSP. returns 0 ok, -1 no perfect matching */
static int ssp(int n,const double*C,const int*rp,const int*ci,double*u,double*v,int*colof,int*rowof,
  double*dist,int*pred,char*fin,int*scanned,HE*heap){
  int i,j;
  for(j=0;j<n;j++){v[j]=INFINITY;}
  for(i=0;i<n;i++)for(int e=rp[i];e<rp[i+1];e++){j=ci[e];if(C[(long)i*n+j]<v[j])v[j]=C[(long)i*n+j];}
  for(j=0;j<n;j++){if(v[j]==INFINITY)return -1;rowof[j]=-1;}
  for(i=0;i<n;i++){double m=INFINITY;int bj=-1;for(int e=rp[i];e<rp[i+1];e++){j=ci[e];double r=C[(long)i*n+j]-v[j];if(r<m||(r==m&&bj>=0&&rowof[bj]>=0&&rowof[j]<0)){m=r;bj=j;}}
    if(bj<0)return -1;u[i]=m;colof[i]=-1;if(rowof[bj]<0){rowof[bj]=i;colof[i]=bj;}}
  for(j=0;j<n;j++){dist[j]=INFINITY;fin[j]=0;}
  for(int s=0;s<n;s++){if(colof[s]>=0)continue;
    int hn=0,ns=0,target=-1;double D=0;
    int touched_n=0; /* reuse scanned for finals; track touched via pred list */
    static int *touched=0; static int tcap=0; if(tcap<n){free(touched);touched=malloc(sizeof(int)*n);tcap=n;}
    for(int e=rp[s];e<rp[s+1];e++){j=ci[e];double d=C[(long)s*n+j]-u[s]-v[j];if(d<dist[j]){if(dist[j]==INFINITY)touched[touched_n++]=j;dist[j]=d;pred[j]=s;hpush(heap,&hn,d,j);}}
    while(hn>0){HE t=hpop(heap,&hn);j=t.j;if(fin[j]||t.d>dist[j])continue;
      if(rowof[j]<0){target=j;D=t.d;break;}
      fin[j]=1;scanned[ns++]=j;i=rowof[j];double dj=dist[j];double ui=u[i];
      for(int e=rp[i];e<rp[i+1];e++){int k=ci[e];if(fin[k])continue;double d=dj+C[(long)i*n+k]-ui-v[k];
        if(d<dist[k]){if(dist[k]==INFINITY)touched[touched_n++]=k;dist[k]=d;pred[k]=i;hpush(heap,&hn,d,k);}}
    }
    if(target<0)return -1;
    for(int q=0;q<ns;q++){j=scanned[q];v[j]+=dist[j]-D;}
    /* augment */
    j=target;for(;;){i=pred[j];int pj=colof[i];rowof[j]=i;colof[i]=j;if(i==s)break;j=pj;}
    for(int q=0;q<ns;q++){j=scanned[q];i=rowof[j];u[i]=C[(long)i*n+j]-v[j];fin[j]=0;}
    u[s]=C[(long)s*n+colof[s]]-v[colof[s]];
    for(int q=0;q<touched_n;q++)dist[touched[q]]=INFINITY;
  }
  return 0;
}

/* returns 0 on success (colof filled), else negative */
int solve(int n,const double*C,int k,int*colof){
  if(k>n)k=n;
  int cap=n*k*2+16; int iter;
  int *cnt=calloc(n,sizeof(int)); int **lst=malloc(sizeof(int*)*n); int *lcap=malloc(sizeof(int)*n);
  for(int i=0;i<n;i++){lcap[i]=4*k+8;lst[i]=malloc(sizeof(int)*lcap[i]);}
  #define ADD(i,j) do{ if(cnt[i]==lcap[i]){lcap[i]*=2;lst[i]=realloc(lst[i],sizeof(int)*lcap[i]);} lst[i][cnt[i]++]=(j);}while(0)
  /* row k smallest via insertion */
  int *bi=malloc(sizeof(int)*(k+1)); double *bd=malloc(sizeof(double)*(k+1));
  for(int i=0;i<n;i++){int m=0;const double*row=C+(long)i*n;
    for(int j=0;j<n;j++){double x=row[j];if(m==k&&x>=bd[k-1])continue;int p=(m<k)?m++:k-1;while(p>0&&bd[p-1]>x){bd[p]=bd[p-1];bi[p]=bi[p-1];p--;}bd[p]=x;bi[p]=j;}
    for(int q=0;q<m;q++)ADD(i,bi[q]);}
  /* col k smallest: process rows, maintain per-col arrays */
  double *cd=malloc(sizeof(double)*n*k); int *cix=malloc(sizeof(int)*n*k); int *cm=calloc(n,sizeof(int));
  for(int i=0;i<n;i++){const double*row=C+(long)i*n;for(int j=0;j<n;j++){double x=row[j];int m=cm[j];double*d=cd+(long)j*k;int*ix=cix+(long)j*k;
    if(m==k&&x>=d[k-1])continue;int p=(m<k)?cm[j]++:k-1;while(p>0&&d[p-1]>x){d[p]=d[p-1];ix[p]=ix[p-1];p--;}d[p]=x;ix[p]=i;}}
  for(int j=0;j<n;j++)for(int q=0;q<cm[j];q++){int i=cix[(long)j*k+q];int dup=0;for(int t=0;t<k&&t<cnt[i];t++)if(lst[i][t]==j){dup=1;break;}if(!dup)ADD(i,j);}
  double*u=malloc(8*n),*v=malloc(8*n),*dist=malloc(8*n);int*rowof=malloc(4*n),*pred=malloc(4*n),*scanned=malloc(4*n);char*fin=malloc(n);
  int *rp=malloc(4*(n+1)); int *ci=NULL; HE*heap=NULL; int ret=-2;
  for(iter=0;iter<20;iter++){
    rp[0]=0;for(int i=0;i<n;i++)rp[i+1]=rp[i]+cnt[i];
    ci=realloc(ci,sizeof(int)*rp[n]);heap=realloc(heap,sizeof(HE)*(rp[n]+n+16));
    for(int i=0;i<n;i++)memcpy(ci+rp[i],lst[i],sizeof(int)*cnt[i]);
    int r=ssp(n,C,rp,ci,u,v,colof,rowof,dist,pred,fin,scanned,heap);
    if(r<0){ /* add more: densify */ for(int i=0;i<n;i++){cnt[i]=0;for(int j=0;j<n;j++)ADD(i,j);} continue;}
    int viol=0;
    for(int i=0;i<n;i++){const double*row=C+(long)i*n;double ui=u[i];for(int j=0;j<n;j++){if(row[j]-ui-v[j]< -1e-12){ADD(i,j);viol++;}}}
    if(!viol){ret=0;break;}
  }
  for(int i=0;i<n;i++)free(lst[i]);free(lst);free(lcap);free(cnt);free(bi);free(bd);free(cd);free(cix);free(cm);
  free(u);free(v);free(dist);free(rowof);free(pred);free(scanned);free(fin);free(rp);free(ci);free(heap);
  return ret;
}
