static inline HE hpop(HE*h,int*n){HE top=h[0];HE x=h[--(*n)];int i=0,N=*n;for(;;){int c=2*i+1;if(c>=N)break;if(c+1<N&&h[c+1].d<h[c].d)c++;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}if(N>0)h[i]=x;return top;}

static double kth(double*a,int n,int kk){int lo=0,hi=n-1;
  while(lo<hi){double pv=a[(lo+hi)>>1];int x=lo,y=hi;
    while(x<=y){while(a[x]<pv)x++;while(a[y]>pv)y--;if(x<=y){double t=a[x];a[x]=a[y];a[y]=t;x++;y--;}}
    if(kk<=y)hi=y;else if(kk>=x)lo=x;else break;}
  return a[kk];}

/* graph: rp, ci, cs (costs). returns 0 ok, -1 failure */
static int ssp(int n,const int*rp,const int*ci,const double*cs,double*u,double*v,int*colof,int*rowof,
  double*dist,int*pred,char*fin,int*scanned,int*touched,int*trow,HE*heap,int*freel,int warm){
  int i,j,nf=0;
  if(warm){
    for(i=0;i<n;i++){double m=INFINITY;for(int e=rp[i];e<rp[i+1];e++){double r=cs[e]-v[ci[e]];if(r<m)m=r;}
      if(m<u[i]-1e-13||colof[i]<0){u[i]=m;j=colof[i];if(j>=0){rowof[j]=-1;colof[i]=-1;}}}
    for(i=0;i<n;i++)if(colof[i]<0)freel[nf++]=i;
  } else {
    for(j=0;j<n;j++){v[j]=INFINITY;rowof[j]=-1;}
    for(i=0;i<n;i++)for(int e=rp[i];e<rp[i+1];e++){j=ci[e];if(cs[e]<v[j])v[j]=cs[e];}
    for(j=0;j<n;j++)if(v[j]==INFINITY)return -1;
    for(i=0;i<n;i++){double m=INFINITY;int bj=-1;for(int e=rp[i];e<rp[i+1];e++){j=ci[e];double r=cs[e]-v[j];if(r<m){m=r;bj=j;}}
      if(bj<0)return -1;u[i]=m;colof[i]=-1;if(rowof[bj]<0){rowof[bj]=i;colof[i]=bj;}else freel[nf++]=i;}
    /* augmenting row reduction, 2 passes */
    for(int pass=0;pass<2;pass++){
      int k=0,cur=nf,nf2=0;int lim=cur*4+16,steps=0;
      while(k<cur && steps<lim){
        steps++;
        i=freel[k++];
        double u1=INFINITY,u2=INFINITY;int j1=-1,j2=-1;
        for(int e=rp[i];e<rp[i+1];e++){j=ci[e];double r=cs[e]-v[j];
          if(r<u2){if(r<u1){u2=u1;j2=j1;u1=r;j1=j;}else{u2=r;j2=j;}}}
        if(j1<0)return -1;
        int i0=rowof[j1];
        if(u1<u2){ if(u2<INFINITY) v[j1]-=u2-u1; else v[j1]-=1.0; }
        else if(i0>=0&&j2>=0){j1=j2;i0=rowof[j2];}
        if(i0>=0){ if(u1<u2) freel[--k]=i0; else freel[nf2++]=i0; }
        rowof[j1]=i;colof[i]=j1;
        if(i0>=0)colof[i0]=-1;
      }
      /* remaining unprocessed into new list */
      while(k<cur)freel[nf2++]=freel[k++];
      nf=nf2;
      if(nf==0)break;
    }
    /* recompute u for all rows: assigned rows u = c - v at assigned, check invariant */
    for(i=0;i<n;i++){double m=INFINITY;int bj=-1;for(int e=rp[i];e<rp[i+1];e++){double r=cs[e]-v[ci[e]];if(r<m){m=r;bj=ci[e];}}
      u[i]=m; (void)bj;}
    /* ensure assigned rows are tight; otherwise unassign */
    nf=0;
    for(i=0;i<n;i++){j=colof[i];if(j>=0){double r=0;int found=0;for(int e=rp[i];e<rp[i+1];e++)if(ci[e]==j){r=cs[e]-v[j];found=1;break;}
        if(!found||r>u[i]+1e-13){rowof[j]=-1;colof[i]=-1;}}
      if(colof[i]<0)freel[nf++]=i;}
  }
  for(j=0;j<n;j++){dist[j]=INFINITY;fin[j]=0;}
  for(int f=0;f<nf;f++){int s=freel[f];
    int hn=0,ns=0,target=-1,tn=0;double D=0;
    for(int e=rp[s];e<rp[s+1];e++){j=ci[e];double d=cs[e]-u[s]-v[j];if(d<dist[j]){if(dist[j]==INFINITY)touched[tn++]=j;dist[j]=d;pred[j]=s;hpush(heap,&hn,d,j);}}
    while(hn>0){HE t=hpop(heap,&hn);j=t.j;if(fin[j]||t.d>dist[j])continue;
      if(rowof[j]<0){target=j;D=t.d;break;}
      fin[j]=1;scanned[ns]=j;i=rowof[j];trow[ns++]=i;double dj=dist[j];double ui=u[i];
      for(int e=rp[i];e<rp[i+1];e++){int k=ci[e];if(fin[k])continue;double d=dj+cs[e]-ui-v[k];
        if(d<dist[k]){if(dist[k]==INFINITY)touched[tn++]=k;dist[k]=d;pred[k]=i;hpush(heap,&hn,d,k);}}
    }
    if(target<0)return -1;
    for(int q=0;q<ns;q++){j=scanned[q];v[j]+=dist[j]-D;}
    j=target;for(;;){i=pred[j];int pj=colof[i];rowof[j]=i;colof[i]=j;if(i==s)break;j=pj;}
    for(int q=0;q<ns;q++)fin[scanned[q]]=0;
    for(int q=0;q<tn;q++)dist[touched[q]]=INFINITY;
    /* recompute u for rows touched: u_i = c(i,col i) - v(col i) */
    for(int q=0;q<ns;q++){i=trow[q];j=colof[i];for(int e=rp[i];e<rp[i+1];e++)if(ci[e]==j){u[i]=cs[e]-v[j];break;}}
    j=colof[s];for(int e=rp[s];e<rp[s+1];e++)if(ci[e]==j){u[s]=cs[e]-v[j];break;}
  }
  return 0;
}

int solve(int n,const double*C,int k,int*colof){
  if(k>n)k=n;
  int *cnt=calloc(n,sizeof(int)); int **lst=malloc(sizeof(int*)*n); int *lcap=malloc(sizeof(int)*n);
  for(int i=0;i<n;i++){lcap[i]=4*k+8;lst[i]=malloc(sizeof(int)*lcap[i]);}
  #define ADD(i,j) do{ if(cnt[i]==lcap[i]){lcap[i]*=2;lst[i]=realloc(lst[i],sizeof(int)*lcap[i]);} lst[i][cnt[i]++]=(j);}while(0)
  /* global threshold from sample */
  int ns=4096; double *smp=malloc(8*ns); unsigned long long st=88172645463325252ULL;
  long N2=(long)n*n;
  for(int s=0;s<ns;s++){st^=st<<13;st^=st>>7;st^=st<<17;smp[s]=C[st%N2];}
  int kk=(int)((double)ns*k/n); if(kk>=ns)kk=ns-1;
  double thr=kth(smp,ns,kk); free(smp);
  double *tmp=malloc(8*n); double *cmin=malloc(8*n); int *carg=malloc(4*n);
  int kmin=k/3; if(kmin<2)kmin=2;
  for(int j=0;j<n;j++){cmin[j]=INFINITY;carg[j]=0;}
  for(int i=0;i<n;i++){const double*row=C+(long)i*n;
    for(int j=0;j<n;j++){double x=row[j];if(x<cmin[j]){cmin[j]=x;carg[j]=i;}if(x<=thr)ADD(i,j);}
    if(cnt[i]<kmin){cnt[i]=0;memcpy(tmp,row,8*n);double t2=kth(tmp,n,kmin-1);for(int j=0;j<n;j++)if(row[j]<=t2)ADD(i,j);}
  }
  for(int j=0;j<n;j++){int i=carg[j];int dup=0;for(int t=0;t<cnt[i];t++)if(lst[i][t]==j){dup=1;break;}if(!dup)ADD(i,j);}
  double*u=malloc(8*n),*v=malloc(8*n),*dist=malloc(8*n);int*rowof=malloc(4*n),*pred=malloc(4*n),*scanned=malloc(4*n),*touched=malloc(4*n),*trow=malloc(4*n),*freel=malloc(4*n);char*fin=malloc(n);
  int *rp=malloc(4*(n+1)); int *ci=NULL; double*cs=NULL; HE*heap=NULL; int ret=-2,warm=0;
  for(int iter=0;iter<12;iter++){
    rp[0]=0;for(int i=0;i<n;i++)rp[i+1]=rp[i]+cnt[i];
    ci=realloc(ci,sizeof(int)*rp[n]);cs=realloc(cs,sizeof(double)*rp[n]);heap=realloc(heap,sizeof(HE)*(rp[n]+n+16));
    for(int i=0;i<n;i++){memcpy(ci+rp[i],lst[i],sizeof(int)*cnt[i]);const double*row=C+(long)i*n;for(int e=rp[i];e<rp[i+1];e++)cs[e]=row[ci[e]];}
    int r=ssp(n,rp,ci,cs,u,v,colof,rowof,dist,pred,fin,scanned,touched,trow,heap,freel,warm);
    if(r<0){ /* enlarge: per-row 2k nearest */
      k=k*2; if(k>n)k=n;
      for(int i=0;i<n;i++){const double*row=C+(long)i*n;memcpy(tmp,row,8*n);double t2=kth(tmp,n,k-1);cnt[i]=0;for(int j=0;j<n;j++)if(row[j]<=t2)ADD(i,j);}
      for(int j=0;j<n;j++){int i=carg[j];int dup=0;for(int t=0;t<cnt[i];t++)if(lst[i][t]==j){dup=1;break;}if(!dup)ADD(i,j);}
      warm=0; continue;}
    int viol=0;
    for(int i=0;i<n;i++){const double*row=C+(long)i*n;double ui=u[i];for(int j=0;j<n;j++){if(row[j]-ui-v[j]< -1e-10){ADD(i,j);viol++;}}}
    if(!viol){ret=0;break;}
    warm=1;
  }
  free(tmp);free(cmin);free(carg);
  for(int i=0;i<n;i++)free(lst[i]);free(lst);free(lcap);free(cnt);
  free(u);free(v);free(dist);free(rowof);free(pred);free(scanned);free(touched);free(trow);free(freel);free(fin);free(rp);free(ci);free(cs);free(heap);
  return ret;
}
